export function BrandTitle({ className }: { className?: string }) {
  const id = useId();
  return (
    <svg role="img" aria-label="Kanakku" viewBox="0 0 3600 1340" className={cn('shrink-0', className)} fillRule="evenodd">
      <defs>
        <linearGradient id={`${id}l`} x1="0" y1="400" x2="0" y2="1170" gradientUnits="userSpaceOnUse">
          <stop stopColor="var(--brand-letter-top)" />
          <stop offset="1" stopColor="var(--brand-letter-base)" />
        </linearGradient>
        <linearGradient id={`${id}s`} x1="0" y1="400" x2="0" y2="970" gradientUnits="userSpaceOnUse">
          <stop stopColor="var(--brand-silver-top)" />
          <stop offset="1" stopColor="var(--brand-silver-base)" />
        </linearGradient>
      </defs>
      <path d={GREY} fill="var(--brand-grey)" />
      <path d={LINES} fill="var(--brand-ink)" />
      <path d="M1432 972L1492 950L1470 1010Z" fill="var(--brand-ink)" />
      <path d={GREEN} fill="var(--brand-trend)" />
      <path d={GOLD} fill="var(--brand-dot)" />
      <path d={LETTERS} fill={`url(#${id}l)`} stroke="var(--brand-edge)" strokeWidth="7" />
      <path d={STEM} fill="var(--brand-stem)" stroke="var(--brand-stem-edge)" strokeWidth="8" />
      <path d={SILVER} fill={`url(#${id}s)`} />
      <path d={COIN} fill="var(--brand-trend)" />
    </svg>
  );
}
